import React, { useCallback, useEffect, useState } from "react";
import * as api from "../api.js";

// Accounts (v0.23): users and API keys, without reaching for curl.
//
// Everything secret is generated by the server and shown exactly once, in a
// box that has to be dismissed on purpose. While one is on screen the drawer
// will not close -- not on Escape, not on a click outside -- because closing it
// would lose a password nobody has written down yet. Destructive or
// credential-changing buttons take two presses (the button turns into a
// confirmation) rather than a browser dialog, which would block the page.
//
// Each action is an ordinary admin API call, so each is written into the
// ledger by the server; a new administrator also raises an alert.

const ROLES = ["viewer", "analyst", "admin"];

function when(iso) {
  return iso ? iso.replace("T", " ").slice(0, 16) : "—";
}

export default function AccountsDrawer({ me, onClose }) {
  const [users, setUsers] = useState(null);
  const [keys, setKeys] = useState(null);
  const [error, setError] = useState(null);
  const [secret, setSecret] = useState(null); // {title, value, note}
  const [copied, setCopied] = useState(false);
  const [confirming, setConfirming] = useState(null); // "reset:<name>" | "revoke:<id>"
  const [busy, setBusy] = useState(false);
  const [newUser, setNewUser] = useState({ username: "", role: "analyst" });
  const [newKeyLabel, setNewKeyLabel] = useState("");

  const load = useCallback(() => {
    Promise.all([api.listUsers(), api.listApiKeys()])
      .then(([u, k]) => { setUsers(u); setKeys(k); })
      .catch((e) => setError(e.message));
  }, []);

  useEffect(() => { load(); }, [load]);

  // Hold the drawer open while a secret is showing. Registered in the capture
  // phase, so it runs before the dashboard's own Escape handler and marks the
  // event handled.
  useEffect(() => {
    if (!secret) return undefined;
    const hold = (e) => { if (e.key === "Escape") e.preventDefault(); };
    window.addEventListener("keydown", hold, true);
    return () => window.removeEventListener("keydown", hold, true);
  }, [secret]);

  const close = () => { if (!secret) onClose(); };

  const run = async (fn) => {
    setBusy(true);
    setError(null);
    try {
      await fn();
      load();
    } catch (e) {
      const problems = e.detail?.problems;
      setError(Array.isArray(problems) ? problems.join("; ")
        : typeof e.detail === "string" ? e.detail : e.message);
    } finally {
      setBusy(false);
      setConfirming(null);
    }
  };

  const show = (title, value, note) => { setCopied(false); setSecret({ title, value, note }); };

  const addUser = (e) => {
    e.preventDefault();
    const name = newUser.username.trim();
    if (!name) return;
    run(async () => {
      const r = await api.createUser(name, newUser.role);
      setNewUser({ username: "", role: newUser.role });
      show(`Password for new ${r.role} '${r.username}'`, r.password,
           "They will be asked to change it the first time they sign in.");
    });
  };

  const reset = (name) => {
    if (confirming !== `reset:${name}`) { setConfirming(`reset:${name}`); return; }
    run(async () => {
      const r = await api.resetUserPassword(name);
      show(`New password for '${name}'`, r.password,
           `${r.sessions_ended} session(s) were signed out. It must be changed at the next sign-in.`);
    });
  };

  const addKey = (e) => {
    e.preventDefault();
    run(async () => {
      const r = await api.createApiKey(newKeyLabel.trim());
      setNewKeyLabel("");
      show(`API key ${r.label ? `'${r.label}'` : r.prefix}`, r.api_key,
           "Send it as the X-API-Key header. Ingest only; it cannot read alerts.");
    });
  };

  const revoke = (k) => {
    if (confirming !== `revoke:${k.id}`) { setConfirming(`revoke:${k.id}`); return; }
    run(() => api.revokeApiKey(k.id));
  };

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(secret.value);
      setCopied(true);
    } catch {
      setCopied(false); // clipboard unavailable; the value is selectable
    }
  };

  return (
    <>
      <div className="drawer-overlay" onClick={close} />
      <div className="drawer accounts-drawer">
        <div className="drawer-head">
          <div className="drawer-actor">Accounts</div>
          <button className="drawer-close" onClick={close} disabled={!!secret}
                  title={secret ? "store the value shown first" : "close"}>&times;</button>
        </div>

        {error && <div className="error-banner">{error}</div>}

        {secret && (
          <div className="secret-box" role="alert">
            <div className="secret-title">{secret.title}</div>
            <code className="secret-value">{secret.value}</code>
            <div className="secret-note">
              Shown once — Shadowfax keeps only a fingerprint. {secret.note}
            </div>
            <div className="secret-actions">
              <button className="btn" onClick={copy}>{copied ? "Copied" : "Copy"}</button>
              <button className="btn primary" onClick={() => setSecret(null)}>
                I have stored it
              </button>
            </div>
          </div>
        )}

        {users === null && !error && <div className="empty-state">Loading…</div>}

        {users && (
          <section className="accounts-section">
            <div className="risk-label">Users</div>
            <table className="lockout-table accounts-users">
              <thead>
                <tr><th>Username</th><th>Role</th><th>Password</th><th>Changed</th><th /></tr>
              </thead>
              <tbody>
                {users.map((u) => (
                  <tr key={u.username}>
                    <td className="mono">{u.username}{u.username === me ? " (you)" : ""}</td>
                    <td><span className={`role-chip ${u.role}`}>{u.role}</span></td>
                    <td>{u.must_change_password
                      ? <span className="lockout-state backoff">must change</span>
                      : <span className="lockout-state">set</span>}</td>
                    <td className="mono">{when(u.password_changed_at)}</td>
                    <td>
                      {u.username !== me && (
                        <button className={`btn${confirming === `reset:${u.username}` ? " danger" : ""}`}
                                disabled={busy || !!secret} onClick={() => reset(u.username)}>
                          {confirming === `reset:${u.username}` ? "Confirm reset" : "Reset password"}
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            <form className="accounts-form" onSubmit={addUser}>
              <input placeholder="new username" value={newUser.username} maxLength={64}
                     onChange={(e) => setNewUser({ ...newUser, username: e.target.value })} />
              <select value={newUser.role}
                      onChange={(e) => setNewUser({ ...newUser, role: e.target.value })}>
                {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
              </select>
              <button className="btn" type="submit"
                      disabled={busy || !!secret || !newUser.username.trim()}>
                Add user
              </button>
            </form>
            <div className="lockout-foot">
              New users get a generated password they must change at first sign-in.
              Your own password is changed from the top bar, which asks for the
              current one.
            </div>
          </section>
        )}

        {keys && (
          <section className="accounts-section">
            <div className="risk-label">API keys</div>
            {keys.length === 0 ? (
              <div className="empty-state">No API keys. Agents and harnesses need one to ingest.</div>
            ) : (
              <table className="lockout-table accounts-keys">
                <thead>
                  <tr><th>Key</th><th>Label</th><th>Created</th><th>Last used</th><th /></tr>
                </thead>
                <tbody>
                  {keys.map((k) => (
                    <tr key={k.id}>
                      <td className="mono">{k.prefix}…</td>
                      <td>{k.label || "—"}</td>
                      <td className="mono">{when(k.created_at)}</td>
                      <td className="mono">{when(k.last_used_at)}</td>
                      <td>
                        <button className={`btn${confirming === `revoke:${k.id}` ? " danger" : ""}`}
                                disabled={busy || !!secret} onClick={() => revoke(k)}>
                          {confirming === `revoke:${k.id}` ? "Confirm revoke" : "Revoke"}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            <form className="accounts-form" onSubmit={addKey}>
              <input placeholder="label, e.g. ci-harness" value={newKeyLabel} maxLength={128}
                     onChange={(e) => setNewKeyLabel(e.target.value)} />
              <button className="btn" type="submit" disabled={busy || !!secret}>New API key</button>
            </form>
            <div className="lockout-foot">
              Revoking a key stops it at once. Issuing and revoking keys are recorded
              in the ledger, with who did it.
            </div>
          </section>
        )}
      </div>
    </>
  );
}
